mapper.update:
update srm_supplier
   set buyer_user_id = #{f.buyerUserId}, pay_terms_cd = #{f.payTermsCd}, currency_cd = #{f.currencyCd},
       country_cd = #{f.countryCd}, control_country_cd = #{f.controlCountryCd}, trade_status = #{f.tradeStatus},
       status_reason = #{f.statusReason}, sec_assessed_on = #{f.secAssessedOn}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where cust_id = #{f.custId} and row_ver = #{f.rowVer}

mapper.select:
select  from srm_supplier_cert
 where cust_id = #{custId}
 order by cert_type_cd, issued_on desc, cert_id desc

mapper.update:
update srm_supplier_cert
   set cert_no = #{f.certNo}, issuer_nm = #{f.issuerNm}, expires_on = #{f.expiresOn}, use_yn = #{f.useYn},
       remark = #{f.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where cert_id = #{id} and row_ver = #{f.rowVer}

mapper.select:
select  from srm_source s join mst_item i on i.item_id = s.item_id
 where s.cust_id = #{custId}
 order by i.item_cd

mapper.update:
update srm_source
   set supplier_item_cd = #{f.supplierItemCd}, supplier_item_nm = #{f.supplierItemNm}, lead_days = #{f.leadDays},
       moq = #{f.moq}, order_mult = #{f.orderMult}, priority = #{f.priority}, use_yn = #{f.useYn}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where source_id = #{id} and row_ver = #{f.rowVer}

mapper.select:
select  from srm_price p join mst_item i on i.item_id = p.item_id
 where p.cust_id = #{custId}
and p.item_id = #{itemId}
 order by i.item_cd, p.currency_cd, p.valid_from desc, p.price_id desc
 limit 2000

mapper.update:
update srm_price
   set valid_to = #{newFrom}::date - 1, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where cust_id = #{custId} and item_id = #{itemId} and currency_cd = #{currencyCd}
   and use_yn = 'Y' and valid_to is null and valid_from < #{newFrom}

update srm_price
   set valid_to = #{validTo}, use_yn = #{useYn}, remark = #{remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where price_id = #{id} and row_ver = #{rowVer}
